document.addEventListener('DOMContentLoaded', function() {
    const width = document.getElementById('bubble-chart').clientWidth;
    const height = document.getElementById('bubble-chart').clientHeight;

    const svg = d3.select('#bubble-chart')
        .append('svg')
        .attr('width', '100%')
        .attr('height', '100%')
        .attr('viewBox', `0 0 ${width} ${height}`);

    const tooltip = d3.select('#tooltip');

    d3.csv('data/stock-descriptions.csv').then(data => {
        // Data processing
        data.forEach(d => {
            d.marketCap = d.marketCap ? +d.marketCap : null;
        });

        // Sort data for determinism
        data.sort((a, b) => a.ticker.localeCompare(b.ticker));

        const sectors = Array.from(new Set(data.map(d => d.sector))).sort();
        const colorScale = d3.scaleOrdinal()
            .domain(sectors)
            .range(d3.schemeCategory10);

        // Radius scale
        const maxCap = d3.max(data, d => d.marketCap) || 1;
        const radiusScale = d3.scaleSqrt()
            .domain([0, maxCap])
            .range([5, 40]);

        const getRadius = d => d.marketCap ? radiusScale(d.marketCap) : 15;

        // Force simulation
        const sectorCenters = {};
        const angleStep = (2 * Math.PI) / sectors.length;
        const radius = Math.min(width, height) / 3;

        sectors.forEach((sector, i) => {
            sectorCenters[sector] = {
                x: width / 2 + radius * Math.cos(i * angleStep),
                y: height / 2 + radius * Math.sin(i * angleStep)
            };
        });

        const simulation = d3.forceSimulation(data)
            .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.1))
            .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.1))
            .force('collide', d3.forceCollide(d => getRadius(d) + 2))
            .force('center', d3.forceCenter(width / 2, height / 2))
            .on('tick', ticked);

        const node = svg.selectAll('.node')
            .data(data)
            .enter()
            .append('g')
            .attr('class', 'node')
            .on('click', (event, d) => selectStock(d.ticker))
            .on('mouseover', function(event, d) {
                if (d.marketCap) {
                    tooltip.transition().duration(200).style('opacity', 0.9);
                    tooltip.html(`<strong>${d.ticker}</strong><br/>${d['full name']}<br/>${d.sector}`)
                        .style('left', (event.pageX + 10) + 'px')
                        .style('top', (event.pageY - 28) + 'px');
                }
            })
            .on('mouseout', function() {
                tooltip.transition().duration(500).style('opacity', 0);
            });

        node.append('circle')
            .attr('r', d => getRadius(d))
            .attr('fill', d => colorScale(d.sector))
            .attr('stroke', d => d3.rgb(colorScale(d.sector)).darker());

        node.append('text')
            .attr('class', 'ticker-label')
            .attr('dy', '.3em')
            .text(d => d.ticker)
            .style('font-size', d => Math.min(getRadius(d) / 1.5, 12) + 'px');

        function ticked() {
            node.attr('transform', d => `translate(${d.x}, ${d.y})`);
        }

        // Render Legend
        const legend = d3.select('#legend');
        sectors.forEach(sector => {
            const item = legend.append('div').attr('class', 'legend-item');
            item.append('div')
                .attr('class', 'legend-color')
                .style('background-color', colorScale(sector));
            item.append('span').text(sector);
        });

        // Render Table
        const tableBody = d3.select('#stock-table tbody');
        const rows = tableBody.selectAll('tr')
            .data(data)
            .enter()
            .append('tr')
            .attr('id', d => `row-${d.ticker}`)
            .on('click', (event, d) => selectStock(d.ticker));

        rows.append('td').text(d => d.ticker);
        rows.append('td').text(d => d['full name']);
        rows.append('td').text(d => d.sector);
        rows.append('td').text(d => formatMarketCap(d.marketCap));

        function formatMarketCap(cap) {
            if (!cap) return 'N/A';
            if (cap >= 1e12) return (cap / 1e12).toFixed(2) + 'T';
            if (cap >= 1e9) return (cap / 1e9).toFixed(2) + 'B';
            if (cap >= 1e6) return (cap / 1e6).toFixed(2) + 'M';
            return cap.toLocaleString();
        }

        function selectStock(ticker) {
            // Highlight circle
            svg.selectAll('circle').classed('selected', false);
            node.filter(d => d.ticker === ticker)
                .select('circle')
                .classed('selected', true);

            // Highlight row
            tableBody.selectAll('tr').classed('selected', false);
            const selectedRow = tableBody.select(`#row-${ticker}`);
            selectedRow.classed('selected', true);

            // Scroll to row
            selectedRow.node().scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
    });
});

